-- Generated by ergasterion/emit.py from declarations/*.yml. Do not edit by hand.
with candidates as (
    select
        source_system as source_system,
        source_fund_id as source_id,
        source_record_id as source_record_id,
        fund_name as fund_name,
        {{ normalise_name('fund_name') }} as normalised_name,
        lei as lei,
        shared_external_id as shared_external_id,
        canonical_vantora_fund_id as canonical_vantora_fund_id,
        asset_class as asset_class,
        strategy as strategy,
        vintage_year as vintage_year,
        currency as currency
    from {{ ref('int_vantora_fund_id_normalised') }} as source


    union all


    select
        source_system as source_system,
        source_fund_id as source_id,
        source_fund_id as source_record_id,
        fund_name as fund_name,
        {{ normalise_name('fund_name') }} as normalised_name,
        lei as lei,
        shared_external_id as shared_external_id,
        cast(null as string) as canonical_vantora_fund_id,
        asset_class as asset_class,
        strategy as strategy,
        vintage_year as vintage_year,
        currency as currency
    from {{ ref('stg_meridex_funds') }} as source


    union all


    select
        source_system as source_system,
        source_fund_id as source_id,
        source_fund_id as source_record_id,
        fund_name as fund_name,
        {{ normalise_name('fund_name') }} as normalised_name,
        lei as lei,
        shared_external_id as shared_external_id,
        cast(null as string) as canonical_vantora_fund_id,
        asset_class as asset_class,
        strategy as strategy,
        vintage_year as vintage_year,
        currency as currency
    from {{ ref('stg_portiq_funds') }} as source


    union all


    select
        source_system as source_system,
        source_fund_id as source_id,
        source_record_id as source_record_id,
        fund_name as fund_name,
        {{ normalise_name('fund_name') }} as normalised_name,
        lei as lei,
        shared_external_id as shared_external_id,
        cast(null as string) as canonical_vantora_fund_id,
        asset_class as asset_class,
        strategy as strategy,
        vintage_year as vintage_year,
        currency as currency
    from {{ ref('stg_chrono_funds') }} as source

),

-- TRANSITIVE ENTITY RESOLUTION. A record must join a cluster if it
-- shares ANY ranked identifier value with the cluster, transitively -- not on its
-- single highest-ranked key alone. Worked example: a Northstar source record that
-- carries only the shared external id (no LEI) still merges with the LEI-keyed
-- Northstar records, because they all carry that same external id. We therefore
-- compute CONNECTED COMPONENTS over the record<->identifier-value graph, then key
-- each cluster on its highest-ranked identifier hash (unchanged golden-key rule).
--
-- Construction: bounded MIN-LABEL propagation, deterministic pure ANSI SQL. Each
-- record's label starts as its own unique key; every round pulls the minimum label
-- across all records sharing an identifier value, so labels flow along identifier
-- edges and every record in a component converges to that component's minimum key.
-- A recursive CTE is deliberately NOT used: both target engines forbid aggregates
-- in the recursive clause and the per-round label pull is an aggregate (min), the
-- same vendor limitation macros/xirr.sql documents and works around with a bounded
-- unrolled chain. The iteration count is FIXED at 5: min-label
-- propagation converges in as many rounds as the component diameter, and the seeded
-- population's components are diameter <= 3 (<= 3 identifier hops), so 5
-- rounds carry a safety margin. Silent under-convergence is caught by
-- tests/assert_res_fund_er_merge_convergence.sql (two records sharing an identifier
-- but landing on different golden keys => propagation stopped early).
keyed as (
    select
        *,
        concat(source_system, '|', source_record_id) as record_key
    from candidates
),

identifier_edges as (
    select
        record_key,
        1 as id_rank,
        'lei' as id_type,
        concat('lei:', upper(lei)) as id_value
    from keyed
    where lei is not null

    union all

    select
        record_key,
        2 as id_rank,
        'shared_external_id' as id_type,
        concat('external:', upper(shared_external_id)) as id_value
    from keyed
    where shared_external_id is not null

    union all

    select
        record_key,
        3 as id_rank,
        'normalised_vantora_fund_id' as id_type,
        concat('vantora:', canonical_vantora_fund_id) as id_value
    from keyed
    where canonical_vantora_fund_id is not null

    union all

    select
        record_key,
        4 as id_rank,
        'normalised_name' as id_type,
        concat('name:', normalised_name) as id_value
    from keyed
    where normalised_name is not null
),

merge_labels_0 as (
    select distinct
        record_key,
        record_key as label
    from identifier_edges
),

merge_values_1 as (
    select
        edges.id_value,
        min(prev.label) as value_label
    from identifier_edges as edges
    inner join merge_labels_0 as prev
        on prev.record_key = edges.record_key
    group by edges.id_value
),

merge_labels_1 as (
    select
        edges.record_key,
        min(vals.value_label) as label
    from identifier_edges as edges
    inner join merge_values_1 as vals
        on vals.id_value = edges.id_value
    group by edges.record_key
),

merge_values_2 as (
    select
        edges.id_value,
        min(prev.label) as value_label
    from identifier_edges as edges
    inner join merge_labels_1 as prev
        on prev.record_key = edges.record_key
    group by edges.id_value
),

merge_labels_2 as (
    select
        edges.record_key,
        min(vals.value_label) as label
    from identifier_edges as edges
    inner join merge_values_2 as vals
        on vals.id_value = edges.id_value
    group by edges.record_key
),

merge_values_3 as (
    select
        edges.id_value,
        min(prev.label) as value_label
    from identifier_edges as edges
    inner join merge_labels_2 as prev
        on prev.record_key = edges.record_key
    group by edges.id_value
),

merge_labels_3 as (
    select
        edges.record_key,
        min(vals.value_label) as label
    from identifier_edges as edges
    inner join merge_values_3 as vals
        on vals.id_value = edges.id_value
    group by edges.record_key
),

merge_values_4 as (
    select
        edges.id_value,
        min(prev.label) as value_label
    from identifier_edges as edges
    inner join merge_labels_3 as prev
        on prev.record_key = edges.record_key
    group by edges.id_value
),

merge_labels_4 as (
    select
        edges.record_key,
        min(vals.value_label) as label
    from identifier_edges as edges
    inner join merge_values_4 as vals
        on vals.id_value = edges.id_value
    group by edges.record_key
),

merge_values_5 as (
    select
        edges.id_value,
        min(prev.label) as value_label
    from identifier_edges as edges
    inner join merge_labels_4 as prev
        on prev.record_key = edges.record_key
    group by edges.id_value
),

merge_labels_5 as (
    select
        edges.record_key,
        min(vals.value_label) as label
    from identifier_edges as edges
    inner join merge_values_5 as vals
        on vals.id_value = edges.id_value
    group by edges.record_key
),

components as (
    select
        record_key,
        label as component_id
    from merge_labels_5
),

component_edges as (
    select
        components.component_id,
        identifier_edges.id_rank,
        identifier_edges.id_type,
        identifier_edges.id_value
    from components
    inner join identifier_edges
        on identifier_edges.record_key = components.record_key
),

component_best_rank as (
    select
        component_id,
        min(id_rank) as best_rank
    from component_edges
    group by component_id
),

component_key as (
    select
        component_edges.component_id,
        min(component_edges.id_value) as cluster_match_key,
        min(component_edges.id_type) as cluster_key_type
    from component_edges
    inner join component_best_rank
        on component_best_rank.component_id = component_edges.component_id
        and component_edges.id_rank = component_best_rank.best_rank
    group by component_edges.component_id
),

component_stats as (
    select
        components.component_id,
        count(distinct keyed.record_key) as cluster_row_count,
        count(distinct keyed.source_system) as cluster_source_count
    from components
    inner join keyed
        on keyed.record_key = components.record_key
    group by components.component_id
),

scored as (
    select
        keyed.*,
        component_key.cluster_match_key as deterministic_match_key,
        component_key.cluster_key_type as exact_key_type,
        component_stats.cluster_row_count as match_row_count,
        component_stats.cluster_source_count as match_source_count
    from keyed
    left join components
        on components.record_key = keyed.record_key
    left join component_key
        on component_key.component_id = components.component_id
    left join component_stats
        on component_stats.component_id = components.component_id
)

select
    source_system as source_system,
    source_id as source_id,
    source_record_id as source_record_id,
    fund_name as fund_name,
    normalised_name as normalised_name,
    deterministic_match_key as deterministic_match_key,
    exact_key_type as exact_key_type,
    case
        when deterministic_match_key is not null
             and (exact_key_type != 'normalised_name' or match_row_count > 1)
            then {{ stable_golden_key('fund', 'deterministic_match_key') }}
    end as golden_fund_key,
    case
        when exact_key_type = 'normalised_vantora_fund_id' then 'tier_0_vantora_id_normalisation'
        when deterministic_match_key is not null
             and (exact_key_type != 'normalised_name' or match_row_count > 1)
            then 'tier_1_deterministic_exact_id'
    end as resolution_tier,
    case
        when deterministic_match_key is not null
             and (exact_key_type != 'normalised_name' or match_row_count > 1)
             and exact_key_type = 'normalised_name'
            then 0.95
        when deterministic_match_key is not null
             and (exact_key_type != 'normalised_name' or match_row_count > 1)
            then 1.00
        else 0.00
    end as confidence,
    not (
        deterministic_match_key is not null
        and (exact_key_type != 'normalised_name' or match_row_count > 1)
    ) as pending_probabilistic,
    lei,
    shared_external_id,
    canonical_vantora_fund_id,
    asset_class,
    strategy,
    vintage_year,
    currency,
    match_row_count,
    match_source_count
from scored
